"""Versioned AVL maps and a rank/population/service-count index.

A save/restore starts a fresh ownership epoch. Older nodes are immutable; an
update copies only old-epoch paths, and may edit nodes owned by its current
branch. This keeps snapshots isolated without allocation on every intermediate
queue operation. Bulk prefix/removal operations also share their search paths.
"""

_epoch = 0


def new_epoch():
    global _epoch
    _epoch += 1


class Node:
    __slots__ = ('key', 'value', 'left', 'right', 'height', 'owner')

    def __init__(self, key, value, left=None, right=None):
        self.key = key
        self.value = value
        self.left = left
        self.right = right
        lh = left.height if left else 0
        rh = right.height if right else 0
        self.height = 1 + (lh if lh > rh else rh)
        self.owner = _epoch


def _node(root, left, right):
    if root.owner != _epoch:
        return Node(root.key, root.value, left, right)
    root.left = left
    root.right = right
    lh = left.height if left else 0
    rh = right.height if right else 0
    root.height = 1 + (lh if lh > rh else rh)
    return root


def _balance(root, left, right):
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        ll, lr = left.left, left.right
        if (ll.height if ll else 0) >= (lr.height if lr else 0):
            return _node(left, ll, _node(root, lr, right))
        new_left = _node(left, ll, lr.left)
        new_right = _node(root, lr.right, right)
        return _node(lr, new_left, new_right)
    if rh > lh + 1:
        rl, rr = right.left, right.right
        if (rr.height if rr else 0) >= (rl.height if rl else 0):
            return _node(right, _node(root, left, rl), rr)
        new_left = _node(root, left, rl.left)
        new_right = _node(right, rl.right, rr)
        return _node(rl, new_left, new_right)
    return _node(root, left, right)


def put(root, key, value):
    if root is None:
        return Node(key, value)
    if key < root.key:
        return _balance(root, put(root.left, key, value), root.right)
    if key > root.key:
        return _balance(root, root.left, put(root.right, key, value))
    if root.owner != _epoch:
        return Node(key, value, root.left, root.right)
    root.value = value
    return root


def get(root, key):
    while root is not None:
        if key < root.key:
            root = root.left
        elif key > root.key:
            root = root.right
        else:
            return root.value
    return None


def pop_min(root):
    """Return (removed node, new root), for a nonempty tree."""
    if root.left is None:
        return root, root.right
    found, left = pop_min(root.left)
    return found, _balance(root, left, root.right)


def pop_max(root):
    if root.right is None:
        return root, root.left
    found, right = pop_max(root.right)
    return found, _balance(root, root.left, right)


def _successor(root, successor):
    if root.owner != _epoch:
        return Node(successor.key, successor.value)
    root.key = successor.key
    root.value = successor.value
    return root


def erase(root, key):
    """Delete a key known to exist."""
    if key < root.key:
        return _balance(root, erase(root.left, key), root.right)
    if key > root.key:
        return _balance(root, root.left, erase(root.right, key))
    if root.left is None:
        return root.right
    if root.right is None:
        return root.left
    left = root.left
    successor, right = pop_min(root.right)
    return _balance(_successor(root, successor), left, right)


def items(root):
    stack = []
    while root is not None or stack:
        while root is not None:
            stack.append(root)
            root = root.left
        root = stack.pop()
        yield root.key, root.value
        root = root.right


def from_sorted(entries):
    def build(lo, hi):
        if lo >= hi:
            return None
        mid = (lo + hi) // 2
        key, value = entries[mid]
        return Node(key, value, build(lo, mid), build(mid + 1, hi))
    return build(0, len(entries))


def _join(root, left, right):
    """AVL join allowing arbitrary differences in subtree heights."""
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        return _balance(left, left.left, _join(root, left.right, right))
    if rh > lh + 1:
        return _balance(right, _join(root, left, right.left), right.right)
    return _node(root, left, right)


def take_min(root, count, output):
    """Remove a prefix in one walk, appending its values to output."""
    if root is None:
        return None, count
    left, count = take_min(root.left, count, output)
    if count == 0:
        return _join(root, left, root.right), 0
    output.append(root.value)
    count -= 1
    if count == 0:
        return root.right, 0
    return take_min(root.right, count, output)


def erase_many(root, keys):
    """Delete sorted existing keys by shared search paths."""
    def descend(node, lo, hi):
        if lo == hi:
            return node
        a, b = lo, hi
        while a < b:
            mid = (a + b) // 2
            if keys[mid] < node.key:
                a = mid + 1
            else:
                b = mid
        cut = a
        left = descend(node.left, lo, cut)
        present = cut < hi and keys[cut] == node.key
        right = descend(node.right, cut + 1 if present else cut, hi)
        if not present:
            return _join(node, left, right)
        if left is None:
            return right
        if right is None:
            return left
        successor, right = pop_min(right)
        return _join(_successor(node, successor), left, right)
    return descend(root, 0, len(keys))


class RankNode:
    __slots__ = ('key', 'live', 'served', 'left', 'right', 'height',
                 'live_total', 'served_total', 'owner')

    def __init__(self, key, live, served, left=None, right=None):
        self.key = key
        self.live = live
        self.served = served
        self.left = left
        self.right = right
        lh = left.height if left else 0
        rh = right.height if right else 0
        self.height = 1 + (lh if lh > rh else rh)
        self.live_total = live + (left.live_total if left else 0) + (right.live_total if right else 0)
        self.served_total = served + (left.served_total if left else 0) + (right.served_total if right else 0)
        self.owner = _epoch


def _rank_node(root, live, served, left, right):
    if root.owner != _epoch:
        return RankNode(root.key, live, served, left, right)
    root.live = live
    root.served = served
    root.left = left
    root.right = right
    lh = left.height if left else 0
    rh = right.height if right else 0
    root.height = 1 + (lh if lh > rh else rh)
    root.live_total = live + (left.live_total if left else 0) + (right.live_total if right else 0)
    root.served_total = served + (left.served_total if left else 0) + (right.served_total if right else 0)
    return root


def _rank_balance(root, left, right):
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        ll, lr = left.left, left.right
        if (ll.height if ll else 0) >= (lr.height if lr else 0):
            new_right = _rank_node(root, root.live, root.served, lr, right)
            return _rank_node(left, left.live, left.served, ll, new_right)
        new_left = _rank_node(left, left.live, left.served, ll, lr.left)
        new_right = _rank_node(root, root.live, root.served, lr.right, right)
        return _rank_node(lr, lr.live, lr.served, new_left, new_right)
    if rh > lh + 1:
        rl, rr = right.left, right.right
        if (rr.height if rr else 0) >= (rl.height if rl else 0):
            new_left = _rank_node(root, root.live, root.served, left, rl)
            return _rank_node(right, right.live, right.served, new_left, rr)
        new_left = _rank_node(root, root.live, root.served, left, rl.left)
        new_right = _rank_node(right, right.live, right.served, rl.right, rr)
        return _rank_node(rl, rl.live, rl.served, new_left, new_right)
    return _rank_node(root, root.live, root.served, left, right)


def rank_add(root, key, live_delta, served_delta=0):
    # Zero-population ranks can remain: there are at most as many distinct
    # ranks on an active branch as enqueue commands in the entire request.
    if root is None:
        return RankNode(key, live_delta, served_delta)
    if key < root.key:
        return _rank_balance(root,
                             rank_add(root.left, key, live_delta, served_delta),
                             root.right)
    if key > root.key:
        return _rank_balance(root, root.left,
                             rank_add(root.right, key, live_delta, served_delta))
    return _rank_node(root, root.live + live_delta, root.served + served_delta,
                      root.left, root.right)


def live_less(root, key):
    total = 0
    while root is not None:
        if key <= root.key:
            root = root.left
        else:
            total += root.live + (root.left.live_total if root.left else 0)
            root = root.right
    return total


def served_greater(root, key):
    total = 0
    while root is not None:
        if key >= root.key:
            root = root.right
        else:
            total += root.served + (root.right.served_total if root.right else 0)
            root = root.left
    return total


def rank_remove_many(root, ranks):
    """Remove sorted resident ranks (duplicates allowed) in one tree walk."""
    def descend(node, lo, hi):
        if lo == hi:
            return node
        a, b = lo, hi
        while a < b:
            mid = (a + b) // 2
            if ranks[mid] < node.key:
                a = mid + 1
            else:
                b = mid
        cut = a
        end = cut
        while end < hi and ranks[end] == node.key:
            end += 1
        left = descend(node.left, lo, cut)
        right = descend(node.right, end, hi)
        return _rank_node(node, node.live - (end - cut), node.served, left, right)
    return descend(root, 0, len(ranks))
